const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={reference_ready:'待拆解',in_review:'待你确认',approved:'可入库',changes_requested:'需要修改',published:'已入库'};
const types={style:'风格',motion:'动作',layout:'布局',background:'背景',combo:'动效模板',template:'动效模板'};
let selectedRevision=null;
let db,selected=new URLSearchParams(location.search).get('project')||'finqube-001',page=new URLSearchParams(location.search).get('page')==='integration'?'integration':'projects',showImport=false,playing=false,raf,toastTimer;
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d;}
function toast(t){$('#wf-toast').textContent=t;$('#wf-toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#wf-toast').style.display='none',4000);}
async function load(){db=await api('/api/workflow');if(!db.projects.some(p=>p.id===selected))selected=db.projects[0]?.id;render();}
const projectFps=()=>current()?.videoConfig?.fps||60;
const lastFrame=()=> (current()?.videoConfig?.durationInFrames||360)-1;
const current=()=>db.projects.find(p=>p.id===selected);
function side(){return `<aside class="wf-nav"><div class="wf-brand">Motion Archive</div><div class="wf-caption">从参考，到可复用的动效。</div><div class="section-label">工作流程</div><button class="nav-item ${page==='projects'?'active':''}" data-action="page" data-value="projects">复现项目<span class="wf-pill">${db.projects.length}</span></button><button class="nav-item ${page==='review'?'active':''}" data-action="page" data-value="review">待确认 / 待入库<span class="wf-pill">${db.projects.filter(p=>['in_review','approved','changes_requested'].includes(p.status)).length}</span></button><div class="section-label">资源库</div><button class="nav-item ${page==='library'?'active':''}" data-action="page" data-value="library">正式资产<span class="wf-pill">${db.assets.length}</span></button><button class="nav-item ${page==='integration'?'active':''}" data-action="page" data-value="integration">AI 调用与导出</button><footer>原始收藏保留在 Eagle<br>复现工程由 Remotion 制作<br>正式资产保存到本地文件</footer></aside>`;}
function importBox(){return showImport?`<section class="wf-import"><label for="eagle-path">从 Eagle 素材创建复现项目</label><input id="eagle-path" placeholder="粘贴 Eagle .info 文件夹中的 MP4 完整路径"><p>读取该素材的 Eagle ID、名称和来源。原片保持在 Eagle，导入后进入待拆解队列，不自动宣称已复现。</p><button class="button primary" data-action="import">读取素材</button></section>`:'';}
function stages(p){const index={reference_ready:0,in_review:2,changes_requested:1,approved:3,published:4}[p.status];return `<div class="wf-stages">${['01 参考素材','02 Remotion 复现','03 对照确认','04 拆解候选','05 正式入库'].map((t,i)=>`<span class="${i===index?'current':i<index?'done':''}">${t}</span>`).join('')}</div>`;}
function candidates(p,historical=false){const canPublish=p.status==='approved'&&!historical;return `<section class="wf-panel" style="margin-top:24px"><div class="wf-panel-head"><h2>拆解候选</h2><small>风格与动效模板分别保存</small></div><div class="wf-inside">${p.candidates.map(c=>`<label class="wf-candidate"><input type="checkbox" name="candidate" value="${c.id}" ${c.selected?'checked':''} ${p.status==='published'||(typeof historical!=='undefined'&&historical)?'disabled':''}><div><strong>${esc(c.name)}</strong><p>${esc(c.description)}</p></div><span class="chip">${types[c.type]}</span></label>`).join('')}<p>布局、背景与运镜保存在模板内部。每项资产记录来源片段、确认版本和运行约束。</p><div class="wf-actions"><button class="button primary" data-action="publish" ${canPublish?'':'disabled'}>${p.status==='published'?'已保存为正式资产':'将选中候选入库'}</button>${p.package?`<a class="button" href="${p.package}" download>下载源码包</a>`:''}</div>${!canPublish&&p.status!=='published'?'<p>先在右侧确认当前复现结果，才会启用入库。</p>':''}</div></section>`;}
function workspace(p){const r=p.revisions.find(v=>v.id===selectedRevision)||p.revisions.at(-1);const historical=r&&r!==p.revisions.at(-1);if(!r)return `<div class="wf-empty"><h2>参考素材已登记</h2><p>下一步由助手分析片段、创建 Remotion 工程并提交复现版本。</p><p>${esc(p.source.name)} · ${p.source.duration||'未知'} 秒</p><code>${esc(p.source.path)}</code></div>`;
return `${stages(p)}<div class="wf-workspace"><div><section class="wf-panel"><div class="wf-panel-head"><h2>原片 / 复现对照</h2><select id="revision-selector" aria-label="选择复现版本">${p.revisions.map(v=>`<option value="${v.id}" ${v.id===r.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div><div class="wf-video-pair"><figure><video id="reference" style="aspect-ratio:${Number(p.source.width)||720}/${Number(p.source.height)||1280}" src="${p.reference}" playsinline muted preload="auto"></video><figcaption><span>原片 · ${p.segment.start}–${p.segment.end}s</span><span>Eagle</span></figcaption></figure><figure><video id="replica" style="aspect-ratio:${Number(p.videoConfig?.width)||Number(p.source.width)||720}/${Number(p.videoConfig?.height)||Number(p.source.height)||1280}" src="${r.video}" playsinline muted preload="auto"></video><figcaption><span>Remotion · ${r.id}</span><span>可编辑重建</span></figcaption></figure></div><div class="wf-controls"><button class="button" data-action="play" id="play-btn">同步播放</button><button class="button" data-action="audio" id="audio-btn">开启复刻声音</button><input type="range" id="compare-scrub" min="0" max="${lastFrame()}" value="0" aria-label="同步逐帧进度"><output id="frame-readout">000 / ${lastFrame()}</output><select id="speed" aria-label="播放速度"><option value="1">1×</option><option value="0.5">0.5×</option><option value="0.25">0.25×</option></select><button class="button" data-action="step" data-value="-1">−1 帧</button><button class="button" data-action="step" data-value="1">+1 帧</button></div><div class="wf-note">暂停后可逐帧对照。播放时两段视频共用进度；编码视频定位存在解码精度限制。精确编辑请打开 Remotion 工程。</div></section>${candidates(p,historical)}</div><aside class="wf-panel"><div class="wf-panel-head"><h2>复现记录</h2><span class="chip blue">${labels[p.status]}</span></div><div class="wf-inside"><dl class="wf-meta"><dt>Eagle ID</dt><dd>${p.source.eagleId}</dd><dt>原片</dt><dd>${p.source.width} × ${p.source.height} · ${p.source.fps||'?'}fps</dd><dt>片段</dt><dd>${p.segment.start}–${p.segment.end} 秒</dd><dt>来源</dt><dd>${/^https?:\/\//.test(p.source.url)?`<a href="${esc(p.source.url)}" target="_blank" rel="noreferrer">打开原始来源 ↗</a>`:'本地素材'}</dd></dl><h3>当前实现</h3><p>${esc(r.notes)}</p><h3>当前差异 / 限制</h3><ul>${r.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="wf-actions"><a class="button" href="${r.video}" download>下载复现视频</a><a class="button" href="${p.studioUrl||'http://127.0.0.1:3011'}" target="_blank">Remotion Studio ↗</a></div><h3>版本记录</h3><ul>${p.revisions.map(v=>`<li><a href="${v.video}" target="_blank">${esc(v.label)}</a> · ${v.review.status==='approved'?'已确认':v.review.status==='published_by_request'?'授权入库 · 助手检查':v.review.status==='changes_requested'?'需修改':'待确认'}</li>`).join('')}</ul><h3>你的判断</h3><textarea id="review-note" placeholder="记录节奏、构图或文字的修改意见…" ${p.status==='published'||(typeof historical!=='undefined'&&historical)?'disabled':''}>${esc(r.review.note)}</textarea><div class="wf-actions"><button class="button" data-action="review" data-value="changes_requested" ${p.status==='published'||(typeof historical!=='undefined'&&historical)?'disabled':''}>需要修改</button><button class="button primary" data-action="review" data-value="approved" ${p.status==='published'||(typeof historical!=='undefined'&&historical)?'disabled':''}>确认复现通过</button></div><div class="wf-review-status">${r.review.status==='published_by_request'?'按本批次授权入库；已做助手检查，未冒充你逐条确认。':r.review.status==='pending'?'尚未确认；未加入正式资产库。':r.review.status==='approved'?'已由你确认通过。':'已记录修改意见，等待下一版。'}</div></div></aside></div>`;}
function library(){return `<div class="wf-top"><div><h1>正式资产</h1><p>仅包含已确认的复现成果，每项都附带可执行源码与来源。</p></div></div>${db.assets.length?`<div class="wf-library">${db.assets.map(a=>`<article><div class="swatch-preview">${types[a.type]}</div><h3>${esc(a.name)}</h3><span class="chip blue">v${a.version}</span><p>${esc(a.description)}</p><p>来源：${esc(a.source.name)}<br>片段 ${a.segment.start}–${a.segment.end}s · ${a.revisionId}</p><a href="${a.package}" download>下载运行包 ↗</a></article>`).join('')}</div>`:'<div class="wf-empty"><h2>等待第一个确认过的复现成果</h2><p>Finqube 复现已进入对照阶段，确认后才能入库。演示样例不会混入这里。</p><button class="button" data-action="page" data-value="review">查看待确认项目</button></div>'}`;}
function integration(){return `<div class="wf-top"><div><h1>AI 调用与导出</h1><p>按表达任务检索完整模板，读取版本固定的使用说明与参数协议。</p></div></div><div class="wf-panel"><div class="wf-inside"><h3>查询与校验</h3><pre class="wf-code">GET /api/assets?q=八步
GET /api/usage?id=editing-workflow
POST /api/usage/plan</pre><h3>本地助手命令</h3><pre class="wf-code">node prototype/workflow/cli.mjs search 八步
node prototype/workflow/cli.mjs usage editing-workflow
node prototype/workflow/cli.mjs plan editing-workflow request.json
node prototype/workflow/cli.mjs usage-check</pre><h3>参数支持级别</h3><p>runtime-prop 为真实运行时参数；source-edit 为需要在派生工程实现的修改要求；consumer 为目标工程的字体、背景或风格加载配置。调用计划只做校验，不会自动改源码或渲染。</p><p>每个模板有自己的时长、画幅、内容容量和光学管线，不再用一组全局默认值代表所有模板。原复刻与几何版入口分别保存。远程连接器未部署，localhost 仅本机可访问。</p></div></div>`;}

function render(){pause();cancelAnimationFrame(raf);const visible=page==='review'?db.projects.filter(p=>['in_review','approved','changes_requested'].includes(p.status)):db.projects;if(page==='review'&&!visible.some(p=>p.id===selected))selected=visible[0]?.id;let content;if(page==='library')content=library();else if(page==='integration')content=integration();else content=`<div class="wf-top"><div><h1>${page==='review'?'待确认 / 待入库':'复现项目'}</h1><p>从 Eagle 参考素材开始，让成功复现的动效逐步成为资产。</p></div><button class="button" data-action="show-import">＋ 从 Eagle 登记</button></div>${importBox()}<div class="wf-projects">${visible.map(p=>`<button class="wf-project ${p.id===selected?'selected':''}" data-action="project" data-id="${p.id}"><strong>${esc(p.title)}</strong><small>${labels[p.status]} · ${p.revisions.length} 个版本</small></button>`).join('')}</div>${current()?workspace(current()):'<div class="wf-empty">当前没有等待确认的项目。</div>'}`;
$('#workflow-root').innerHTML=`<div class="wf-shell">${side()}<main class="wf-main">${content}</main></div>`;for(const v of document.querySelectorAll('video'))v.addEventListener('error',()=>toast('视频尚未就绪，请等待渲染完成后刷新。'),{once:true});}
function pause(){playing=false;document.querySelectorAll('video').forEach(v=>v.pause());if($('#play-btn'))$('#play-btn').textContent='同步播放';}
function seek(frame){pause();const t=Math.max(0,Math.min(lastFrame(),frame))/projectFps();document.querySelectorAll('video').forEach(v=>{v.currentTime=t;});$('#compare-scrub').value=String(Math.round(t*projectFps()));$('#frame-readout').textContent=String(Math.round(t*projectFps())).padStart(3,'0')+' / '+lastFrame();}
function tick(){if(!playing)return;const a=$('#reference'),b=$('#replica');if(!a||!b)return;if(a.ended||b.ended){seek(0);return;}if(Math.abs(a.currentTime-b.currentTime)>.08)b.currentTime=a.currentTime;$('#compare-scrub').value=String(Math.min(lastFrame(),Math.round(a.currentTime*projectFps())));$('#frame-readout').textContent=String(Math.min(lastFrame(),Math.round(a.currentTime*projectFps()))).padStart(3,'0')+' / '+lastFrame();raf=requestAnimationFrame(tick);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;if(a==='page'){if(b.dataset.value==='library'){location.href='/index.html';return;}page=b.dataset.value;render();}if(a==='project'){selected=b.dataset.id;selectedRevision=null;render();}if(a==='show-import'){showImport=!showImport;render();}if(a==='import'){const p=await api('/api/import-eagle',{path:$('#eagle-path').value});selected=p.id;showImport=false;page='projects';await load();toast('Eagle 素材已登记');}if(a==='audio'){const v=$('#replica');v.muted=!v.muted;b.textContent=v.muted?'开启复刻声音':'关闭复刻声音';}if(a==='play'){if(playing){pause();return;}await Promise.all([...document.querySelectorAll('video')].map(v=>v.play()));playing=true;$('#play-btn').textContent='暂停';tick();}if(a==='step')seek(Number($('#compare-scrub').value)+Number(b.dataset.value));if(a==='review'){pause();const p=current();b.disabled=true;await api(`/api/projects/${p.id}/review`,{revisionId:p.revisions.at(-1).id,status:b.dataset.value,note:$('#review-note').value});await load();toast(b.dataset.value==='approved'?'已确认，可选择候选并入库':'修改意见已保存');}if(a==='publish'){b.disabled=true;await api(`/api/projects/${current().id}/publish`,{ids:[...document.querySelectorAll('[name=candidate]:checked')].map(x=>x.value)});location.href='/index.html';}}catch(e){b.disabled=false;toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.id==='compare-scrub')seek(Number(e.target.value));});document.addEventListener('change',e=>{if(e.target.id==='revision-selector'){selectedRevision=e.target.value;render();}if(e.target.id==='speed')document.querySelectorAll('video').forEach(v=>v.playbackRate=Number(e.target.value));});
$('#workflow-root').innerHTML='<div class="wf-loader">正在读取本地复现项目…</div>';load().catch(e=>{$('#workflow-root').innerHTML=`<div class="wf-empty"><h2>未连接工作流服务</h2><p>${esc(e.message)}</p><p>启动：node prototype/workflow/server.mjs</p></div>`;});
